package dev.grimholt.server.api;
import dev.grimholt.api.ServiceRegistry; import java.util.*; import java.util.concurrent.ConcurrentHashMap;
public final class DefaultServiceRegistry implements ServiceRegistry { private final ConcurrentHashMap<Class<?>,Object> services=new ConcurrentHashMap<>(); public <T> void register(Class<T> t,T s){if(t==null||s==null)throw new NullPointerException();if(services.putIfAbsent(t,s)!=null)throw new IllegalStateException("Service already registered: "+t.getName());} public <T> Optional<T> find(Class<T> t){return Optional.ofNullable(t.cast(services.get(t)));} public <T> T require(Class<T> t){return find(t).orElseThrow(()->new IllegalStateException("Missing service: "+t.getName()));} public <T> boolean unregister(Class<T> t,T s){return services.remove(t,s);} public void clear(){services.clear();}}
